import { css, CSSResultGroup, html, LitElement, nothing, PropertyValues } from "lit";
import { property, state } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";

import {
  addCustomState,
  AttachInternals,
  customElement,
  deleteCustomState,
  DesignToken,
  hasCustomState,
  ReconnectedCallback,
  registerStyleSheet,
  setCustomState,
} from "@m3e/web/core";

import { SelectionManager, selectionManager } from "@m3e/web/core/a11y";
import { Breakpoint, M3eBreakpointObserver } from "@m3e/web/core/layout";
import { M3eDirectionality, SupportsDirectionality } from "@m3e/web/core/bidi";

import { M3eStepElement } from "./StepElement";
import { isStepLabelPosition, StepLabelPosition } from "./StepLabelPosition";
import { isStepHeaderPosition, StepHeaderPosition } from "./StepHeaderPosition";
import { isStepperOrientation, StepperOrientation } from "./StepperOrientation";

/**
 * Provides a wizard-like workflow by dividing content into logical steps.
 *
 * @description
 * The `m3e-stepper` component orchestrates a structured, wizard-like workflow by dividing
 * content into discrete, navigable steps. It supports horizontal and vertical orientations,
 * linear progression, and configurable label and header positioning.
 *
 * @example
 * Showcase: Basic usage. Import `@m3e/web/stepper`. Also import `@m3e/web/form-field`, `@m3e/web/button`.
 *
 * ```html
 * <m3e-stepper>
 *   <m3e-step for="step1">Fill out your name</m3e-step>
 *   <m3e-step for="step2">Fill out your address</m3e-step>
 *   <m3e-step for="step3">Done</m3e-step>
 *   <m3e-step-panel id="step1">
 *     <form>
 *       <m3e-form-field>
 *         <label slot="label" for="name">Name</label>
 *         <input name="name" id="name" required />
 *       </m3e-form-field>
 *     </form>
 *     <div slot="actions">
 *       <m3e-button><m3e-stepper-next>Next</m3e-stepper-next></m3e-button>
 *     </div>
 *   </m3e-step-panel>
 *   <m3e-step-panel id="step2">
 *     <form>
 *       <m3e-form-field>
 *         <label slot="label" for="address">Address</label>
 *         <input name="address" id="address" required />
 *       </m3e-form-field>
 *     </form>
 *     <div slot="actions">
 *       <m3e-button><m3e-stepper-previous>Back</m3e-stepper-previous></m3e-button>
 *       <m3e-button><m3e-stepper-next>Next</m3e-stepper-next></m3e-button>
 *     </div>
 *   </m3e-step-panel>
 *   <m3e-step-panel id="step3">
 *     Done
 *     <div slot="actions">
 *       <m3e-button><m3e-stepper-previous>Back</m3e-stepper-previous></m3e-button>
 *       <m3e-button><m3e-stepper-reset>Reset</m3e-stepper-reset></m3e-button>
 *     </div>
 *   </m3e-step-panel>
 * </m3e-stepper>
 * ```
 *
 * @example
 * Showcase: Orientation. Import `@m3e/web/stepper`.
 *
 * ```html
 * <m3e-stepper orientation="vertical">
 *   <!-- Content omitted for brevity -->
 * </m3e-stepper>
 * ```
 *
 * @example
 * Showcase: Header positions. Import `@m3e/web/stepper`.
 *
 * ```html
 * <m3e-stepper header-position="below">
 *   <!-- Content omitted for brevity -->
 * </m3e-stepper>
 * ```
 *
 * @example
 * Showcase: Label positions. Import `@m3e/web/stepper`.
 *
 * ```html
 * <m3e-stepper label-position="below">
 *   <!-- Content omitted for brevity -->
 * </m3e-stepper>
 * ```
 *
 * @example
 * Showcase: Linear stepper. Import `@m3e/web/stepper`.
 *
 * ```html
 * <m3e-stepper linear>
 *   <m3e-step for="step1" editable>Fill out your name</m3e-step>
 *   <m3e-step for="step2" editable>Fill out your address</m3e-step>
 *   <m3e-step for="step3">Done</m3e-step>
 *   <!-- Content omitted for brevity -->
 * </m3e-stepper>
 * ```
 *
 * @tag m3e-stepper
 *
 * @attr header-position - The position of the step header, when oriented horizontally.
 * @attr label-position - The position of the step labels, when oriented horizontally.
 * @attr linear - Whether the validity of previous steps should be checked or not.
 * @attr orientation - The orientation of the stepper.
 *
 * @slot step - Renders a step.
 * @slot panel - Renders a panel.
 *
 * @fires beforeinput - Dispatched before the selected state of a step changes.
 * @fires input - Dispatched when the selected state of a step changes.
 * @fires change - Dispatched when the selected step changes.
 *
 * @cssprop --m3e-step-divider-thickness - Thickness of the divider line between steps.
 * @cssprop --m3e-step-divider-color - Color of the divider line between steps.
 * @cssprop --m3e-step-divider-inset - Inset offset for divider alignment within step layout.
 */
@customElement("m3e-stepper")
export class M3eStepperElement extends SupportsDirectionality(ReconnectedCallback(AttachInternals(LitElement))) {
  static {
    registerStyleSheet(css`
      m3e-stepper:is(:state(--vertical), :--vertical) > [slot="panel"] {
        margin-inline-start: calc(var(--m3e-step-padding, 24px) + calc(var(--m3e-step-icon-size, 24px) / 2));
      }
      m3e-stepper:is(:state(--vertical), :--vertical) > [slot="panel"]:not(:is(:state(--last), :--last)) {
        border-inline-start-width: var(--m3e-step-divider-thickness, 1px);
        border-inline-start-style: solid;
        border-inline-start-color: var(--m3e-step-divider-color, ${DesignToken.color.outline});
      }
      m3e-stepper:is(:state(--vertical), :--vertical) > [slot="step"]:not(:is(:state(--first), :--first))::before,
      m3e-stepper:is(:state(--vertical), :--vertical) > [slot="step"]:not(:is(:state(--last), :--last))::after {
        margin-inline-start: calc(var(--m3e-step-padding, 24px) + calc(var(--m3e-step-icon-size, 24px) / 2));
        border-inline-start-width: var(--m3e-step-divider-thickness, 1px);
        border-inline-start-style: solid;
        border-inline-start-color: var(--m3e-step-divider-color, ${DesignToken.color.outline});
      }
      m3e-stepper:is(:state(--rtl), :--rtl):is(:state(--vertical), :--vertical)
        > [slot="step"]:not(:is(:state(--first), :--first))::before,
      m3e-stepper:is(:state(--rtl), :--rtl):is(:state(--vertical), :--vertical)
        > [slot="step"]:not(:is(:state(--last), :--last))::after {
        right: 0;
      }
    `);
  }

  /** The styles of the element. */
  static override styles: CSSResultGroup = css`
    :host {
      display: flex;
      flex-direction: column;
      position: relative;
    }
    :host([hidden]) {
      display: none;
    }
    .header {
      contain: layout style;
    }
    :host(:not(:is(:state(--vertical), :--vertical))) .header {
      display: flex;
      align-items: flex-start;
      flex-wrap: nowrap;
    }
    :host(:is(:state(--vertical), :--vertical)) .header {
      display: contents;
    }
    :host(:is(:state(--vertical), :--vertical)) ::slotted([slot="step"]) {
      flex: none;
    }
    :host(:is(:state(--vertical), :--vertical)) ::slotted([slot="step"]:not(:is(:state(--first), :--first)))::before,
    :host(:is(:state(--vertical), :--vertical)) ::slotted([slot="step"]:not(:is(:state(--last), :--last)))::after {
      content: "";
      display: block;
      position: absolute;
      left: 0;
    }
    :host(:is(:state(--vertical), :--vertical)) ::slotted([slot="step"]:not(:is(:state(--first), :--first)))::before {
      top: 0;
      bottom: calc(100% - var(--m3e-step-padding, 24px) + var(--m3e-step-divider-inset, 8px));
    }
    :host(:is(:state(--vertical), :--vertical)) ::slotted([slot="step"]:not(:is(:state(--last), :--last)))::after {
      top: calc(100% - var(--m3e-step-padding, 24px) + var(--m3e-step-divider-inset, 8px));
      bottom: 0;
    }
    :host(:not(:is(:state(--vertical), :--vertical))) {
      --m3e-collapsible-animation-duration: 0ms;
    }
    :host(:is(:state(--no-animate), :--no-animate)) {
      --m3e-collapsible-animation-duration: 0ms;
    }
  `;

  /** @private */ #breakpointUnobserve?: () => void;
  /** @private */ #directionalitySubscription?: () => void;
  /** @private */ @state() private _orientation?: Exclude<StepperOrientation, "auto">;
  /** @private */ @state() private _selectedIndex: number | null = null;
  /** @internal */ readonly [selectionManager] = new SelectionManager<M3eStepElement>()
    .withHomeAndEnd()
    .withWrap()
    .onSelectedItemsChange(() => this.#handleSelectedChange())
    .withDirectionality(M3eDirectionality.current);

  /**
   * The position of the step header, when oriented horizontally.
   * @default "above"
   */
  @property({ attribute: "header-position", reflect: true, useDefault: true }) headerPosition: StepHeaderPosition =
    "above";

  /**
   * The position of the step labels, when oriented horizontally.
   * @default "end"
   */
  @property({ attribute: "label-position", reflect: true, useDefault: true }) labelPosition: StepLabelPosition = "end";

  /**
   * Whether the validity of previous steps should be checked or not.
   * @default false
   */
  @property({ type: Boolean, reflect: true }) linear = false;

  /**
   * The orientation of the stepper.
   * @default "horizontal"
   */
  @property({ reflect: true, useDefault: true }) orientation: StepperOrientation = "horizontal";

  /** The steps. */
  get steps(): readonly M3eStepElement[] {
    return this[selectionManager]?.items ?? [];
  }

  /** The selected step. */
  get selectedStep(): M3eStepElement | null {
    return this._selectedIndex !== null ? (this.steps[this._selectedIndex] ?? null) : null;
  }

  /** The zero-based index of the selected step. */
  get selectedIndex(): number {
    return this._selectedIndex ?? -1;
  }

  /**
   * Moves the stepper to the previous step.
   * @returns {boolean} Whether the stepper moved to the previous step.
   */
  movePrevious(): boolean {
    return this.moveTo((this._selectedIndex ?? 1) - 1);
  }

  /**
   * Moves the stepper to the next step.
   * @returns {boolean} Whether the stepper moved to the next step.
   */
  moveNext(): boolean {
    return this.moveTo((this._selectedIndex ?? -1) + 1);
  }

  /**
   * Moves the stepper to the step with the specified index.
   * @param index The zero-based index of the step to which to move.
   * @returns {boolean} Whether the stepper moved to the specified `index`.
   */

  moveTo(index: number): boolean {
    if (this._moveTo(index)) {
      this.dispatchEvent(new Event("change", { bubbles: true }));
      return true;
    }
    return false;
  }

  /** @internal */
  _moveTo(index: number): boolean {
    const selectedStep = this.selectedStep;
    if (selectedStep && selectedStep.index === index) {
      return true;
    }

    if (this.steps[index]?.disabled) {
      return false;
    }

    if (index >= 0 && index < this.steps.length) {
      if (selectedStep) {
        const valid = this.#checkValidity();
        if (this.linear) {
          if (index < selectedStep.index) {
            const previousStep = this[selectionManager].items[index];
            if (!previousStep || (previousStep.completed && !previousStep.editable)) {
              return false;
            }
          } else if (index > selectedStep.index + 1) {
            const nextStep = this[selectionManager].items[index];
            if (!nextStep || !nextStep.completed) {
              return false;
            }
          } else if (!valid && !selectedStep.optional) {
            return false;
          }
        }

        selectedStep.completed = true;
      }

      this._selectedIndex = index;
      this[selectionManager].select(this.selectedStep);
      return true;
    }
    return false;
  }

  /** Resets the stepper to its initial state, clearing any form data. */
  reset(): void {
    this.steps.forEach((x) => x.reset());
    const index = this.steps.findIndex((x) => !x.disabled);
    if (index !== this._selectedIndex) {
      this._selectedIndex = index;
      this[selectionManager].select(this.selectedStep);
      this.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  /** @inheritdoc */
  override connectedCallback(): void {
    super.connectedCallback();

    this.#applyOrientation();
    this.#applyHeaderPosition();
    this.#applyLabelPosition();

    addCustomState(this, "--no-animate");
    this.#directionalitySubscription = M3eDirectionality.observe(
      () => (this[selectionManager].directionality = M3eDirectionality.current),
    );
  }

  /** @inheritdoc */
  override disconnectedCallback(): void {
    super.disconnectedCallback();

    this._orientation = undefined;
    this.#breakpointUnobserve?.();
    this.#directionalitySubscription?.();
  }

  /** @inheritdoc */
  override reconnectedCallback(): void {
    super.reconnectedCallback();

    if (this.orientation === "auto") {
      this.#initBreakpointMonitoring();
    }
  }

  /** @inheritdoc */
  protected override willUpdate(changedProperties: PropertyValues): void {
    super.willUpdate(changedProperties);

    if (changedProperties.has("headerPosition")) {
      this.#applyHeaderPosition();
    }

    if (changedProperties.has("orientation")) {
      this.#applyOrientation();
      this.#breakpointUnobserve?.();

      if (this.orientation === "auto") {
        this.#initBreakpointMonitoring();
      } else {
        this._orientation = undefined;
        this.#updateDisplayOrder();
      }
    }
    if (changedProperties.has("_orientation")) {
      this.#updateDisplayOrder();
    }

    if (changedProperties.has("labelPosition")) {
      this.#applyLabelPosition();
      this.#updateLabelPosition();
    }
  }

  /** @inheritdoc */
  protected override firstUpdated(_changedProperties: PropertyValues<this>): void {
    super.firstUpdated(_changedProperties);

    if (!_changedProperties.has("orientation")) {
      this.#updateDisplayOrder();
    }
    if (!_changedProperties.has("labelPosition")) {
      this.#updateLabelPosition();
    }
  }

  /** @inheritdoc */
  protected override render(): unknown {
    let panelIndex: number | undefined;
    if (this.selectedStep?.panel) {
      panelIndex = [...this.querySelectorAll("[slot='panel']")].indexOf(this.selectedStep.panel);
      if (panelIndex === -1) {
        panelIndex = undefined;
      }
    }

    if (!this[selectionManager].vertical) {
      return html`${this.headerPosition === "above" ? this.#renderHeader() : nothing}
        <m3e-slide class="steps" selected-index="${ifDefined(panelIndex)}">
          <slot name="panel"></slot>
        </m3e-slide>
        ${this.headerPosition === "below" ? this.#renderHeader() : nothing}`;
    }

    return html`${this.#renderHeader()} <slot name="panel"></slot>`;
  }

  /** @private */
  #applyOrientation(): void {
    if (!isStepperOrientation(this.orientation)) {
      this.orientation = "horizontal";
    }
  }

  /** @private */
  #applyLabelPosition(): void {
    if (!isStepLabelPosition(this.labelPosition)) {
      this.labelPosition = "end";
    }
  }

  /** @private */
  #applyHeaderPosition(): void {
    if (!isStepHeaderPosition(this.headerPosition)) {
      this.headerPosition = "above";
    }
  }

  /** @private */
  #renderHeader(): unknown {
    return html`<div
      class="header"
      role="tablist"
      aria-orientation="${ifDefined(this[selectionManager].vertical ? "vertical" : undefined)}"
      @change=${this.#handleChange}
    >
      <slot name="step" @slotchange=${this.#handleSlotChange} @keydown=${this.#handleKeyDown}></slot>
    </div>`;
  }

  /** @private */
  #handleChange(e: Event): void {
    e.stopPropagation();
    this.dispatchEvent(new Event("change", { bubbles: true }));
  }

  /** @private */
  #handleSlotChange(): void {
    const { added, removed } = this[selectionManager].setItems([...this.querySelectorAll("m3e-step")]);
    if (added.length > 0 || removed.length > 0) {
      for (let i = 0; i < this[selectionManager].items.length; i++) {
        this[selectionManager].items[i].index = i;
      }

      this.#updateDisplayOrder();
      this.#updateLabelPosition();

      if (this[selectionManager].selectedItems.length == 0) {
        this[selectionManager].select(this[selectionManager].items.find((x) => !x.disabled));
      }
    }
  }

  /** @private */
  #handleKeyDown(e: KeyboardEvent): void {
    this[selectionManager].onKeyDown(e);
  }

  /** @private */
  #handleSelectedChange(): void {
    const selected = this[selectionManager].selectedItems[0];
    let selectedIndex = selected ? this.steps.indexOf(selected) : null;
    if (selectedIndex === -1) {
      selectedIndex = null;
    }
    this._selectedIndex = selectedIndex;

    for (const step of this[selectionManager].items) {
      if (step.panel) {
        step.panel.active = step.index === selectedIndex;
      }
    }

    if (selected && this.matches(":focus-within") && !selected.matches(":focus")) {
      selected.focus();
    }

    if (hasCustomState(this, "--no-animate")) {
      requestAnimationFrame(() => deleteCustomState(this, "--no-animate"));
    }
  }

  /** @private */
  #checkValidity(): boolean {
    let valid = false;
    if (this.selectedStep) {
      valid = this.selectedStep.panel?.querySelector("form")?.checkValidity() ?? true;
      if (this.selectedStep.optional) {
        valid = true;
      }
      this.selectedStep.invalid = !valid;
    }
    return valid;
  }

  /** @private */
  #initBreakpointMonitoring(): void {
    this.#breakpointUnobserve = M3eBreakpointObserver.observe([Breakpoint.XSmall], (matches) => {
      this._orientation = matches.get(Breakpoint.XSmall) ? "vertical" : "horizontal";
      this.#updateDisplayOrder();
    });
  }

  /** @private */
  #updateDisplayOrder(): void {
    this[selectionManager].vertical = (this._orientation ?? this.orientation) === "vertical";
    setCustomState(this, "--vertical", this[selectionManager].vertical);

    if (!this[selectionManager].vertical) {
      this.steps.forEach((x, i, arr) => {
        x.style.order = "";
        deleteCustomState(x, "--vertical");
        setCustomState(x, "--first", i === 0);
        setCustomState(x, "--last", i === arr.length - 1);
        if (x.panel) {
          x.panel.style.order = "";
        }
      });
    } else {
      this.steps.forEach((x, i, arr) => {
        x.style.order = `${i}`;
        addCustomState(x, "--vertical");
        setCustomState(x, "--first", i === 0);
        setCustomState(x, "--last", i === arr.length - 1);
        if (x.panel) {
          x.panel.style.order = `${i}`;
        }
      });
    }
  }

  /** @private */
  #updateLabelPosition(): void {
    this.steps.forEach((x) => setCustomState(x, "--label-below", this.labelPosition === "below"));
  }
}

declare global {
  interface HTMLElementTagNameMap {
    "m3e-stepper": M3eStepperElement;
  }
}
